import { useState } from 'react'
import { useCurrentOrganization } from './useCurrentOrganization'
import { useGetOrganizations } from './useGetOrganizations'
import Purchases from 'react-native-purchases'
import retry from 'async-retry'
import { CreditProductId, RevenueCatSubscriptionProductId } from '@/types'

export const usePurchase = ({ onSuccess }: { onSuccess: () => void }) => {
	const [isPurchasing, setIsPurchasing] = useState(false)
	const { currentOrganization } = useCurrentOrganization()
	const { refetch: refetchOrganizations } = useGetOrganizations()

	const purchase = async (
		productId: CreditProductId | RevenueCatSubscriptionProductId
	) => {
		if (!currentOrganization) return
		setIsPurchasing(true)
		try {
			await Purchases.setAttributes({
				organizationId: currentOrganization.id,
				userId: await Purchases.getAppUserID()
			})
			const products = await Purchases.getProducts([productId])
			await Purchases.purchaseStoreProduct(products[0])
			await retry(
				async () => {
					const result = await refetchOrganizations()
					if (
						BigInt(result.data?.organizations?.edges[0]?.node?.creditBalance) >
							BigInt(currentOrganization.creditBalance) ||
						result.data?.organizations?.edges[0]?.node?.plan !==
							currentOrganization.plan
					) {
						return
					}
					throw new Error('Purchase failed')
				},
				{
					factor: 2,
					retries: 10,
					minTimeout: 500,
					maxTimeout: 5000
				}
			)
			onSuccess()
		} catch (error) {
			console.warn('Purchase failed:', error)
		} finally {
			setIsPurchasing(false)
		}
	}
	return {
		isPurchasing,
		purchase
	}
}
